using System;
using UnityEngine;

namespace Yeeun.SymbolPuzzle
{
    /// <summary>
    /// Maps each <see cref="SymbolShape"/> to a mesh asset. The meshes are generated by
    /// the editor menu "Tools/Yeeun/Symbol Puzzle/Regenerate Symbol Meshes", or can be
    /// replaced with hand-modelled meshes by the art team.
    /// </summary>
    [CreateAssetMenu(fileName = "SymbolMeshLibrary", menuName = "Yeeun/Symbol Puzzle/Symbol Mesh Library")]
    public class SymbolMeshLibrary : ScriptableObject
    {
        [Serializable]
        public struct Entry
        {
            public SymbolShape shape;
            public Mesh mesh;
        }

        public Entry[] entries = Array.Empty<Entry>();

        public Mesh Get(SymbolShape shape)
        {
            foreach (var e in entries)
                if (e.shape == shape) return e.mesh;
            return null;
        }
    }
}
